package io.github.ivoryprd.shoten.ocr

import io.github.ivoryprd.shoten.lookup.Language
import io.github.ivoryprd.shoten.util.Cjk
import java.io.InputStream

/**
 * Characters that look like others, which the recognizer may have read instead: the kana and
 * common kanji (and hanzi), each with the characters it looks most like. The tables are
 * generated by tools/similar_chars.py and loaded when first needed.
 */
class SimilarChars(private val open: (path: String) -> InputStream) {
    private val tables = HashMap<Language, Map<String, String>>()

    /** The characters that [char] may be mistaken for, the most alike first. */
    fun of(char: String, language: Language): List<String> =
        table(language)[char]?.let { list -> Cjk.codePoints(list).map { String(Character.toChars(it)) }.toList() }.orEmpty()

    /** The kana and kanji (or hanzi) the table has: the common ones. */
    fun characters(language: Language): List<String> =
        table(language).keys.filter { c -> c.codePointCount(0, c.length) == 1 && c.codePointAt(0).let { Cjk.isHan(it) || Cjk.isKana(it) } }.sorted()

    @Synchronized
    private fun table(language: Language): Map<String, String> = tables.getOrPut(language) {
        open(if (language == Language.CHINESE) "similar/zh.txt" else "similar/ja.txt").use(::parse)
    }

    companion object {
        /** Reads a table: a character, a tab and its look-alikes per line; lines starting with # are comments. */
        fun parse(input: InputStream): Map<String, String> {
            val table = HashMap<String, String>()
            input.bufferedReader().forEachLine { line ->
                val tab = line.indexOf('\t')
                if (tab > 0 && !line.startsWith("#")) table[line.substring(0, tab)] = line.substring(tab + 1)
            }
            return table
        }
    }
}
